def check_good_triples():
    good_triples = []

    print("Checking triples (x, y, z) for 1 <= x, y, z <= 10...")

    for x in range(1, 11):
        for y in range(1, 11):
            for z in range(1, 11):
                # Numerator: (x+1)^y
                numerator = (x + 1)**y
                # Denominator: x^z + 1
                denominator = x**z + 1

                # Check if the result is an integer
                if denominator != 0 and numerator % denominator == 0:
                    good_triples.append((x, y, z))

    print("\n--- Results ---")
    print(f"Total number of good triples found: {len(good_triples)}")
    print("List of good triples (x, y, z):")
    for triple in good_triples:
        print(triple)

    return good_triples

